    private void showBoundary(String id,JSONObject match){JSONObject peer=sub(sub(match,"boundary"),"peer");StringBuilder info=new StringBuilder(UiStrings.t("请先阅读并尊重对方的交流边界。\n"));JSONArray limits=array(peer,"limits");String[] levels={"yes","maybe","no"},labels={UiStrings.t("可以"),UiStrings.t("需要沟通"),UiStrings.t("不接受")};for(int i=0;i<3;i++){ArrayList<String> values=new ArrayList<>();for(int j=0;j<limits.length();j++){JSONObject item=limits.optJSONObject(j);if(item!=null&&levels[i].equals(value(item,"level")))values.add(value(item,"item"));}if(!values.isEmpty())info.append("\n").append(labels[i]).append("：").append(android.text.TextUtils.join("、",values));}String safeword=value(peer,"safeword");if(!safeword.isEmpty())info.append(UiStrings.t("\n安全词：")).append(safeword);new SiteDialog.Builder(this,palette).setTitle(UiStrings.t("交流边界确认")).setMessage(info.toString()).setPositiveButton(UiStrings.t("已阅读并确认"),(d,w)->request("POST","/matches/"+id+"/boundary-ack",new JSONObject(),r->chat(id))).setNeutralButton(UiStrings.t("查看名片"),(d,w)->push(()->profile(value(sub(match,"user"),"id")))).setNegativeButton(UiStrings.t("稍后"),null).show();}
