    private void sendChat(String id,JSONObject payload,Runnable complete){if(chatSending||!id.equals(chatId)||!chatAllowed())return;try{String key=payload.toString();if(!key.equals(pendingMessageKey)){pendingMessageKey=key;pendingMessageClientId=UUID.randomUUID().toString();}payload.put("clientId",pendingMessageClientId);}catch(JSONException e){return;}chatSending=true;applyChatState();int expected=screen;api.call("POST","/matches/"+id+"/messages",payload,(r,error)->{if(screen!=expected||!id.equals(chatId))return;chatSending=false;applyChatState();if(error!=null){showFailure(error);return;}pendingMessageKey="";pendingMessageClientId="";complete.run();appendMessage(obj(r));chatScroll.post(()->chatScroll.fullScroll(View.FOCUS_DOWN));refreshCounters();});}
