        JSONObject media=m.optJSONObject("media");if(media!=null){if("image".equals(type)||"image".equals(value(media,"kind"))){AnimatedPhotoView image=new AnimatedPhotoView(this);image.palette(palette);image.setBackground(rounded(IMAGE_BG,10));image.setClipToOutline(true);image.setScaleType(ImageView.ScaleType.CENTER_CROP);bubble.addView(image,new LinearLayout.LayoutParams(Math.min(maxWidth,dp(200)),dp(170)));api.image(image,media,true);image.setOnClickListener(v->showImage(media));}else{Button audio=button(UiStrings.t("▶ 播放语音"),()->playAudio(media));audio.setTextSize(13);bubble.addView(audio,new LinearLayout.LayoutParams(Math.min(maxWidth,dp(170)),dp(40)));}}
        TextView time=text(ChatPresentation.time(value(m,"createdAt"),"HH:mm"),10,mine?0xffffe1dd:MUTED);time.setGravity(Gravity.END);LinearLayout.LayoutParams timeLp=new LinearLayout.LayoutParams(-1,-2);timeLp.topMargin=dp(3);bubble.addView(time,timeLp);
