    private void pickMedia(String mime,String purpose,String match,Consumer<JSONObject> done){
        uploadReady=done;uploadPurpose=purpose;uploadMatch=match;uploadScreen=screen;
        // The system grants access to the selected item only. Never request library
        // access, enumerate albums, or persist access to the selected file.
        Intent chooser;
        if(Build.VERSION.SDK_INT>=33&&mime.equals("image/*")){
            chooser=new Intent(android.provider.MediaStore.ACTION_PICK_IMAGES);chooser.setType("image/*");
        }else{
            chooser=new Intent(Intent.ACTION_OPEN_DOCUMENT);chooser.setType(mime);chooser.addCategory(Intent.CATEGORY_OPENABLE);
        }
        chooser.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
        try{startActivityForResult(chooser,700);}catch(ActivityNotFoundException e){
            Intent fallback=new Intent(Intent.ACTION_OPEN_DOCUMENT);fallback.setType(mime);fallback.addCategory(Intent.CATEGORY_OPENABLE);fallback.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
            try{startActivityForResult(fallback,700);}catch(ActivityNotFoundException unavailable){uploadReady=null;notice(UiStrings.t("没有可用的文件选择器"));}
        }
    }
    private void reviewUpload(Uri uri,String purpose,String match,Consumer<JSONObject> done,java.io.File local){
        final int expected=screen;final Dialog[] dialog={null};dialog[0]=MediaUploadForm.show(this,api,palette,me,uri,purpose,match,local,media->{if(screen==expected&&!isFinishing())done.accept(media);},error->{if(screen==expected&&!isFinishing())showFailure(error);},()->mediaDialogs.remove(dialog[0]));mediaDialogs.add(dialog[0]);
    }
    @Override protected void onActivityResult(int request,int result,Intent data){
        super.onActivityResult(request,result,data);
        if(request==705){Consumer<Uri> picked=chatImagePicked;chatImagePicked=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&picked!=null)picked.accept(data.getData());return;}
        if(request==704){if(result==RESULT_OK&&data!=null&&data.getData()!=null)scanQrImage(data.getData());return;}
        if(request==701){byte[] image=pendingShareImage;pendingShareImage=null;if(result==RESULT_OK&&data!=null&&data.getData()!=null&&image!=null){try(java.io.OutputStream output=getContentResolver().openOutputStream(data.getData())){if(output==null)throw new java.io.IOException("No output stream");output.write(image);notice(UiStrings.t("分享图片已保存"));}catch(java.io.IOException error){notice(UiStrings.t("保存图片失败"));}}return;}
        if(request!=700||uploadReady==null)return;
        Consumer<JSONObject> done=uploadReady;uploadReady=null;
        if(result!=RESULT_OK||data==null||data.getData()==null||uploadScreen!=screen)return;
        reviewUpload(data.getData(),uploadPurpose,uploadMatch,done,null);
    }
    private void playAudio(JSONObject media){
        if(!"show".equals(media.optString("view","show"))){notice(UiStrings.t("此附件暂不可用"));return;}
        String url=value(media,"url");Uri uri=Uri.parse(url);String host=uri.getHost();
        if(!"https".equals(uri.getScheme())||host==null||!(host.equals("erp.sex")||host.endsWith(".erp.sex"))){notice(UiStrings.t("附件链接不可用"));return;}
        Dialog dialog=new Dialog(this);LinearLayout content=column();content.setPadding(dp(24),dp(24),dp(24),dp(24));TextView status=text(UiStrings.t("正在加载语音…"),16,TEXT);add(content,status);android.media.MediaPlayer player=new android.media.MediaPlayer();
        player.setAudioAttributes(new android.media.AudioAttributes.Builder().setUsage(android.media.AudioAttributes.USAGE_MEDIA).setContentType(android.media.AudioAttributes.CONTENT_TYPE_SPEECH).build());
        Button play=primary(UiStrings.t("暂停"),()->{if(player.isPlaying()){player.pause();status.setText(UiStrings.t("已暂停"));}else{player.start();status.setText(UiStrings.t("正在播放"));}});play.setEnabled(false);add(content,play);dialog.setContentView(content);
        dialog.setOnDismissListener(d->player.release());player.setOnPreparedListener(p->{play.setEnabled(true);p.start();status.setText(UiStrings.t("正在播放"));});player.setOnCompletionListener(p->status.setText(UiStrings.t("播放完毕，可点击再次播放")));player.setOnErrorListener((p,what,extra)->{status.setText(UiStrings.t("无法播放此附件，请检查网络或文件格式"));return true;});dialog.show();
        try{player.setDataSource(this,uri);player.prepareAsync();}catch(Exception e){status.setText(UiStrings.t("无法播放此附件"));}
    }

