    private void applyAppearance(){ThemePalette previous=palette,next=resolvePalette();palette=next;usePalette(next);if(root!=null)recolorView(root,previous,next);if(profileSheet!=null&&profileSheet.isShowing())recolorView(profileSheet.getWindow().getDecorView(),previous,next);if(firstRunSheet!=null&&firstRunSheet.isShowing())firstRunSheet.palette(next);if(matchSuccessSheet!=null&&matchSuccessSheet.isShowing())matchSuccessSheet.palette(next);if(modeSegment!=null)modeSegment.palette(next);if(nav!=null){nav.setBackgroundColor(palette.pop?BG:SURFACE);for(int i=0;i<nav.getChildCount();i++){nav.getChildAt(i).setBackground(palette.pop&&i==tab?outlined(ACCENT,10):null);navIcons[i].tint(i==tab?(palette.pop?Color.WHITE:ACCENT):MUTED);navLabels[i].setTextColor(i==tab?(palette.pop?Color.WHITE:ACCENT):MUTED);}}updatePreferenceChoices();if(divider!=null)divider.setBackgroundColor(BORDER);if(themeButton!=null)updateThemeIcon();if(verification!=null&&previous.dark!=next.dark)verification.appearance(next.dark);setTheme(getResources().getIdentifier(next.dark?"AppTheme":"AppThemeLight","style",getPackageName()));updateSystemBars();}
    private void recolorView(View view,ThemePalette old,ThemePalette next){
        if(view instanceof TextView){TextView t=(TextView)view;t.setTextColor(old.recolor(t.getCurrentTextColor(),next));if(t instanceof EditText)t.setHintTextColor(next.muted);}
        if(view instanceof PullRefreshLayout)((PullRefreshLayout)view).palette(next);
        if(view instanceof PostComposer)((PostComposer)view).palette(next);
        if(view instanceof PostDiscussion)((PostDiscussion)view).palette(next);
        if(view instanceof SuperLikeButton)((SuperLikeButton)view).palette(next);
        if(view instanceof ProfileActionButton)((ProfileActionButton)view).palette(next);
        if(view instanceof ProfileReactionBar){((ProfileReactionBar)view).palette(next);return;}
        if(view instanceof SiteIconView)((SiteIconView)view).recolor(old,next);
        if(view instanceof AnimatedPhotoView)((AnimatedPhotoView)view).palette(next);
        if(view instanceof MatchGroupSkeletonView)((MatchGroupSkeletonView)view).palette(next);
        android.graphics.drawable.Drawable bg=view.getBackground();
        if("group_empty_icon".equals(view.getTag())&&bg instanceof GradientDrawable)((GradientDrawable)bg).setColor((next.accent&0x00ffffff)|0x1a000000);
        if(bg instanceof GradientDrawable){GradientDrawable d=(GradientDrawable)bg;if(d instanceof PopDrawable)((PopDrawable)d).line(next.border);if(d.getColor()!=null)d.setColor(old.recolor(d.getColor().getDefaultColor(),next));if("theme_border".equals(view.getTag()))d.setStroke(next.pop?Math.round(2.5f*getResources().getDisplayMetrics().density):dp(1),next.border);else if("choice_selected".equals(view.getTag()))d.setStroke(dp(2),0xffff5a4e);}
        else if(bg instanceof android.graphics.drawable.ColorDrawable){android.graphics.drawable.ColorDrawable d=(android.graphics.drawable.ColorDrawable)bg;d.setColor(old.recolor(d.getColor(),next));}
        if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++)recolorView(group.getChildAt(i),old,next);}
    }
