    private void openSourceProject(){
        Uri project=Uri.parse("https://github.com/BuaichiZY/erp_app");
        Intent browser=new Intent(Intent.ACTION_MAIN).addCategory(Intent.CATEGORY_APP_BROWSER);
        android.content.pm.PackageManager manager=getPackageManager();
        android.content.pm.ResolveInfo preferred=manager.resolveActivity(browser,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY);
        LinkedHashSet<String> packages=new LinkedHashSet<>();
        if(preferred!=null&&preferred.activityInfo!=null&&!"android".equals(preferred.activityInfo.packageName))packages.add(preferred.activityInfo.packageName);
        for(android.content.pm.ResolveInfo candidate:manager.queryIntentActivities(browser,0))if(candidate.activityInfo!=null)packages.add(candidate.activityInfo.packageName);
        for(String browserPackage:packages)try{
            startActivity(new Intent(Intent.ACTION_VIEW,project).addCategory(Intent.CATEGORY_BROWSABLE).setPackage(browserPackage));return;
        }catch(ActivityNotFoundException ignored){}
        notice(UiStrings.t("没有可用的浏览器"));
    }
